"""Hive auto-rig: Unreal scene builder (generated by hive-rig).

Imports every character of a hive-rig scene and builds its Control Rig, each
from its own builder script next to this one (`<character>_unreal.py`, into
/Game/HiveRig/<character>), then stands a Skeletal Mesh actor of each in the
open level where the scene places it.

A prop held across characters gets a socket on the holder's Skeletal Mesh at
the holding bone (`held_<character>_<control>`). A Control Rig only sees its
own character's bones, so the prop of one Skeletal Mesh can't follow another
actor's hand inside Unreal: attach a separate prop mesh to that socket, or
bake the hold in Blender or Maya.

Run in the Output Log (Python): py "<this file>"
"""

import json
import os

import unreal

SCENE = json.loads(r"""__HIVE_SCENE_JSON__""")
HERE = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
CHARACTERS = {}  # name -> the character script's globals


def to_ue_location(p):
    """A place in the scene (metres, Y up, +Z forward) in Unreal (cm, Z up)."""
    return unreal.Vector(p[0] * 100.0, p[2] * 100.0, p[1] * 100.0)


def load_character(c):
    path = os.path.join(HERE, c["script"])
    if not os.path.isfile(path):
        raise RuntimeError("hive-rig: %s is missing; export %s from the scene again" % (path, c["name"]))
    ns = {"__name__": "hive_scene_" + c["name"], "__file__": path}
    with open(path) as f:
        exec(compile(f.read(), path, "exec"), ns)
    return ns


def spawn(mesh, location):
    """A Skeletal Mesh actor in the open level, or None without one."""
    try:
        actors = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
        return actors.spawn_actor_from_object(mesh, location, unreal.Rotator(0.0, 0.0, 0.0))
    except Exception as e:  # no level open, or an older editor
        unreal.log_warning("hive-rig: couldn't place %s in the level: %s" % (mesh, e))
        return None


def add_socket(mesh, name, bone):
    """A socket on a Skeletal Mesh at a bone. True when it could be added."""
    try:
        socket = unreal.SkeletalMeshSocket(outer=mesh)
        socket.set_editor_property("socket_name", name)
        socket.set_editor_property("bone_name", bone)
        mesh.add_socket(socket, False)
        return True
    except Exception as e:
        unreal.log_warning("hive-rig: couldn't add socket %s on %s: %s" % (name, bone, e))
        return False


def build():
    meshes, actors = {}, {}
    for c in SCENE["characters"]:
        ns = load_character(c)
        CHARACTERS[c["name"]] = ns
        ns["main"]([])  # import, build the Control Rig and its menus
        meshes[c["name"]] = ns["find_skeletal_mesh"]()
        actors[c["name"]] = spawn(meshes[c["name"]], to_ue_location(c["offset"]))
    sockets = []
    for h in SCENE["holds"]:
        name = "held_%s_%s" % (h["prop_character"], h["prop_control"])
        if add_socket(meshes[h["holder_character"]], name, h["holder_bone"]):
            sockets.append(name)
        unreal.log("hive-rig: %s's %s is held by %s's %s: socket %s (attach a prop mesh to it)"
                   % (h["prop_character"], h["prop_control"], h["holder_character"], h["holder_bone"], name))
    return meshes, actors, sockets


def main():
    meshes, actors, sockets = build()
    unreal.log("hive-rig: scene %s with %d characters and %d held-prop sockets"
               % (SCENE["name"], len(meshes), len(sockets)))
    return meshes, actors, sockets


if __name__ == "__main__":
    main()
